Object.assign(laoText,{'A little ritual, just for you':'ຊ່ວງເວລານ້ອຍໆ ເພື່ອຕົວທ່ານ','Beauty, in':'ຄວາມງາມໃນ','your own way.':'ແບບຂອງທ່ານເອງ','The Ruby edit':'ຄັດສັນໂດຍ Ruby','Our little philosophy':'ແນວຄິດຂອງພວກເຮົາ','A little something new':'ສິ່ງໃໝ່ສຳລັບທ່ານ','Find your everyday favorite':'ຄົ້ນຫາສິ່ງທີ່ມັກໃນທຸກມື້','You may also love':'ທ່ານອາດຈະມັກ','Your little treats':'ຂອງພິເສດສຳລັບທ່ານ','Almost yours':'ໃກ້ຈະເປັນຂອງທ່ານແລ້ວ','Rose Petal':'ກີບກຸຫຼາບ','Soft Nude':'ນູດອ່ອນ','Berry Kiss':'ເບີຣີ','ไอเท็มบิวตี้ที่คัดสรรมาอย่างตั้งใจ เพื่อเติมความสุขเล็ก ๆ ให้ทุกวันของคุณ':'ຜະລິດຕະພັນຄວາມງາມທີ່ຄັດສັນຢ່າງໃສ່ໃຈ ເພີ່ມຄວາມສຸກນ້ອຍໆໃຫ້ທຸກມື້ຂອງທ່ານ','บิวตี้ไอเท็มที่อยากให้คุณได้ลอง':'ຜະລິດຕະພັນຄວາມງາມທີ່ຢາກໃຫ້ທ່ານລອງ','ชิ้นโปรดของเรา':'ສິນຄ້າຂາຍດີ','ความสวยที่เริ่ม':'ຄວາມງາມເລີ່ມຕົ້ນ','จากการรักตัวเอง':'ຈາກການຮັກຕົນເອງ','ความสวยในแบบที่เป็นคุณ':'ຄວາມງາມໃນແບບຂອງທ່ານ','ดูสินค้าทั้งหมด':'ເບິ່ງສິນຄ້າທັງໝົດ','เลือกชมสินค้าของเรา':'ເລືອກຊົມສິນຄ້າຂອງພວກເຮົາ','รู้จัก Ruby Room':'ຮູ້ຈັກ Ruby Room','ค้นพบสิ่งที่ใช่':'ຄົ້ນພົບສິ່ງທີ່ເໝາະກັບທ່ານ','ลิปออยล์บำรุงริมฝีปาก':'ລິບອອຍບຳລຸງຮິມຝີປາກ','มอยส์เจอไรเซอร์ผิวเนียนนุ่ม':'ຄຣີມບຳລຸງຜິວໃຫ້ນຸ່ມນຽນ','บลัชเนื้อซอฟต์แมตต์':'ບລັຊເນື້ອແມັດນຸ່ມ','เซรั่มเติมความชุ่มชื้น':'ເຊຣັ່ມເພີ່ມຄວາມຊຸ່ມຊື່ນ','ลิปทินต์เนื้อกำมะหยี่':'ລິບທິນເນື້ອກຳມະຫຍີ່','คลีนเซอร์เนื้อน้ำนม':'ຄລີນເຊີເນື້ອນ້ຳນົມ','อายแชโดว์โทนอบอุ่น':'ອາຍແຊໂດວໂທນອົບອຸ່ນ','สลีปปิ้งมาสก์กุหลาบ':'ມາສກ໌ກຸຫຼາບສຳລັບກາງຄືນ','ความชุ่มชื้น':'ຄວາມຊຸ່ມຊື່ນ','ผลิตภัณฑ์บิวตี้ที่ออกแบบมาเพื่อเป็นส่วนหนึ่งของช่วงเวลาดูแลตัวเอง ใช้ง่าย สบายผิว และเหมาะกับทุกวัน':'ຜະລິດຕະພັນຄວາມງາມສຳລັບຊ່ວງເວລາດູແລຕົນເອງ ໃຊ້ງ່າຍ ສະບາຍຜິວ ແລະ ເໝາະກັບທຸກມື້','ส่งฟรีเมื่อช้อปครบ ฿1,500':'ສົ່ງຟຣີເມື່ອຊື້ຄົບ ฿1,500','ของขวัญชิ้นเล็กในทุกออเดอร์':'ຮັບຂອງຂວັນນ້ອຍໆໃນທຸກຄຳສັ່ງຊື້','ขอบคุณที่เลือก Ruby Room':'ຂອບໃຈທີ່ເລືອກ Ruby Room','เราได้รับคำสั่งซื้อของคุณแล้ว':'ພວກເຮົາໄດ້ຮັບຄຳສັ່ງຊື້ຂອງທ່ານແລ້ວ','หมายเลขคำสั่งซื้อ':'ໝາຍເລກຄຳສັ່ງຊື້','ทีมงานจะติดต่อกลับเพื่อยืนยันการจัดส่งค่ะ':'ທີມງານຈະຕິດຕໍ່ກັບເພື່ອຢືນຢັນການຈັດສົ່ງ'});
function toLao(html){return Object.entries(laoText).sort((a,b)=>b[0].length-a[0].length).reduce((out,[th,lo])=>out.split(th).join(lo),html)}
Object.assign(laoText,{'น้ำหอม':'ນ້ຳຫອມ','สเปรย์ล็อกเมกอัพ':'ສະເປຣຍລັອກເມກອັບ'});
const money=(n,currency='THB')=>currency==='LAK'?`${Number(n).toLocaleString('en-US')} ກີບ`:'฿'+Number(n).toLocaleString('th-TH');
const priceOf=(product,amount=product.price)=>money(amount,product.currency||'THB');
function currencyTotals(items=cart){return items.reduce((totals,item)=>{const currency=item.currency||'THB';totals[currency]=(totals[currency]||0)+item.price*item.qty;return totals},{})}
function formatCurrencyTotals(totals){return Object.entries(totals).map(([currency,total])=>money(total,currency)).join(' + ')||money(0)}
function cartShipping(totals){if(totals.THB!==undefined){let fee=totals.THB>=1500?0:50;return {value:fee,label:totals.LAK!==undefined?`${fee?money(fee):'ຟຣີ'} · ຄ່າສົ່ງສິນຄ້າກີບຢືນຢັນກັບຮ້ານ`:fee?money(fee):'ຟຣີ'}}return {value:0,label:'ຢືນຢັນຄ່າຈັດສົ່ງກັບຮ້ານ'}}
function save(){localStorage.setItem('ruby-cart',JSON.stringify(cart));document.querySelector('#cartCount').textContent=cart.reduce((s,i)=>s+i.qty,0)}
function toast(msg){toastEl.textContent=toLao(msg);toastEl.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>toastEl.classList.remove('show'),2300)}
function productCard(p){return `<article class="product-card" data-detail="${p.id}"><div class="product-image"><img src="${p.image}" alt="${p.name}" loading="lazy"/><span class="product-tag">${p.tag}</span><button class="quick-add" data-add="${p.id}">ເພີ່ມໃສ່ກະຕ່າ　＋</button></div><div class="product-name">${p.name}</div>${p.variant&&!p.name.includes(p.variant)?`<p class="product-variant">${p.variant}</p>`:''}<p class="product-description">${p.desc}</p><div class="price">${priceOf(p)}${p.old?`<span class="old-price">${priceOf(p,p.old)}</span>`:''}</div></article>`}
function home(){return `<section class="hero store-hero"><div class="hero-copy store-copy"><span class="eyebrow">Ruby Room Beauty</span><h1 class="store-info-title">ຂໍ້ມູນຮ້ານ<br/><em>Ruby Room Beauty</em></h1><div class="store-details"><div class="store-detail"><span>ທີ່ຕັ້ງຮ້ານ</span><p>ບ້ານຄຳຮຸ່ງ ເມືອງໄຊທານີ ນະຄອນຫຼວງວຽງຈັນ</p></div><div class="store-detail"><span>ເບີໂທຕິດຕໍ່</span><p>02092298999</p></div><div class="store-detail"><span>ເວລາເປີດ-ປິດ</span><p>10:00-22:00</p></div></div></div></section><section class="section"><div class="section-heading"><div><span class="eyebrow">The Ruby edit</span><h2>ສິນຄ້າຂາຍດີ</h2></div><p>ຜະລິດຕະພັນທີ່ຄັດສັນມາໃຫ້ທ່ານ</p></div><div class="product-grid">${products.slice(0,4).map(productCard).join('')}</div><div style="text-align:center;margin-top:32px"><a class="button button-outline" href="#shop">ເບິ່ງສິນຄ້າທັງໝົດ</a></div></section><section class="section"><div class="section-heading"><div><span class="eyebrow">A little something new</span><h2>ຄົ້ນພົບສິນຄ້າໃໝ່</h2></div><a class="text-link" href="#shop">ເລືອກຊົມທັງໝົດ　→</a></div><div class="product-grid">${products.slice(4).map(productCard).join('')}</div></section>`}
function shop(){let list=products.filter(p=>(filter==='ทั้งหมด'||p.category===filter)&&(!searchTerm||(`${p.name} ${p.desc}`).toLowerCase().includes(searchTerm.toLowerCase())));return `<div class="page-wrap"><div class="breadcrumbs"><a href="#home">หน้าแรก</a>　/　ร้านค้าทั้งหมด</div><span class="eyebrow">Find your everyday favorite</span><h1 class="page-title">ร้านค้าทั้งหมด</h1><p class="page-subtitle">ของดีชิ้นเล็ก ๆ ที่ช่วยให้วันธรรมดาพิเศษขึ้น</p><div class="shop-layout"><aside class="filters"><div class="filter-group"><p class="filter-label">หมวดหมู่</p>${['ทั้งหมด','เมคอัพ','สกินแคร์','น้ำหอม','ขนตาปลอม','สเปรย์ล็อกเมกอัพ'].map(x=>`<label><input type="radio" name="category" value="${x}" ${filter===x?'checked':''}>${x==='ขนตาปลอม'?'ຂົນຕາປອມ':x==='สเปรย์ล็อกเมกอัพ'?'ສະເປຣຍລັອກເມກອັບ':x}</label>`).join('')}</div><div class="filter-group"><p class="filter-label">ราคา</p><label><input type="checkbox">ต่ำกว่า ฿700</label><label><input type="checkbox">฿700 – ฿1,000</label><label><input type="checkbox">มากกว่า ฿1,000</label></div></aside><div><div class="shop-toolbar"><span>แสดง ${list.length} รายการ</span><select class="sort-select" id="sortProducts"><option value="featured">เรียงตาม: แนะนำ</option><option value="low">ราคา: ต่ำไปสูง</option><option value="high">ราคา: สูงไปต่ำ</option></select></div><div class="product-grid inner-grid" id="shopProducts">${list.map(productCard).join('')||'<p>ไม่พบสินค้าที่ค้นหา</p>'}</div></div></div></div>`}
function detail(id){let p=products.find(x=>x.id===id)||products[0],hasStock=Boolean(p.stock),categoryLabel=p.category==='ขนตาปลอม'?'ຂົນຕາປອມ':p.category==='สเปรย์ล็อกเมกอัพ'?'ສະເປຣຍລັອກເມກອັບ':p.category;return `<div class="page-wrap"><div class="breadcrumbs"><a href="#home">ໜ້າຫຼັກ</a>　/　<a href="#shop">ຮ້ານຄ້າ</a>　/　${p.name}</div><div class="detail-layout"><div><img class="detail-main-image" src="${p.image}" alt="${p.name}"/><div class="detail-thumbs"><button class="selected"><img src="${p.image}" alt="${p.name}"/></button></div></div><div class="detail-copy"><span class="eyebrow">${categoryLabel} · RUBY ROOM BEAUTY</span><h1>${p.name}</h1>${p.brand?`<p class="brand-line">ຍີ່ຫໍ້: ${p.brand}</p>`:''}${p.rating?`<span class="stars">★★★★★　${p.rating} รีวิว</span>`:''}<div class="detail-price">${priceOf(p)}</div><p>${p.desc}${hasStock?'':' ຜະລິດຕະພັນບິວຕີ້ທີ່ອອກແບບມາເພື່ອຊ່ວງເວລາດູແລຕົນເອງ ໃຊ້ງ່າຍ ສະບາຍຜິວ ແລະ ເໝາະກັບທຸກມື້'}</p>${hasStock?`<p class="stock-info">ຈຳນວນສິນຄ້າ: ${p.stock} ${p.stockUnit||'ຊິ້ນ'}</p>`:`<h4>ເລືອກສີ</h4><div class="swatches"><button class="selected">Rose Petal</button><button>Soft Nude</button><button>Berry Kiss</button></div>`}<h4>ຈຳນວນ</h4><div class="buy-row"><div class="qty"><button data-qty="-">−</button><input id="detailQty" value="1" min="1" max="${p.stock||99}" inputmode="numeric" aria-label="ຈຳນວນສິນຄ້າ"/><button data-qty="+">＋</button></div><button class="button" data-add="${p.id}">ເພີ່ມໃສ່ກະຕ່າ　·　${priceOf(p)}</button></div><div class="detail-note">♡　ຈັດສົ່ງຟຣີເມື່ອສັ່ງຊື້ຄົບ ฿1,500<br/>✧　ຫໍ່ສິນຄ້າຢ່າງໃສ່ໃຈ</div></div></div><section class="section"><div class="section-heading"><div><span class="eyebrow">You may also love</span><h2>ສິນຄ້າທີ່ທ່ານອາດມັກ</h2></div></div><div class="product-grid">${products.filter(x=>x.id!==p.id).slice(0,4).map(productCard).join('')}</div></section></div>`}
function cartPage(){if(!cart.length)return `<div class="page-wrap"><div class="breadcrumbs"><a href="#home">ໜ້າຫຼັກ</a>　/　ກະຕ່າສິນຄ້າ</div><div class="empty-state"><div class="empty-icon">♡</div><h2>ກະຕ່າຂອງທ່ານຍັງວ່າງຢູ່</h2><p>ລອງເລືອກສິນຄ້າທີ່ທ່ານມັກ ແລ້ວກັບມາທີ່ນີ້</p><a class="button" href="#shop">ເລືອກຊົມສິນຄ້າ</a></div></div>`;let totals=currencyTotals(),shipping=cartShipping(totals),grand={...totals};if(shipping.value)grand.THB=(grand.THB||0)+shipping.value;return `<div class="page-wrap"><div class="breadcrumbs"><a href="#home">ໜ້າຫຼັກ</a>　/　ກະຕ່າສິນຄ້າ</div><span class="eyebrow">Your little treats</span><h1 class="page-title">ກະຕ່າສິນຄ້າ <small style="font:12px 'Noto Sans Lao';color:#8b8078">(${cart.reduce((s,i)=>s+i.qty,0)} ຊິ້ນ)</small></h1><p class="page-subtitle">ກວດສອບລາຍການສິນຄ້າກ່ອນດຳເນີນການຕໍ່</p><div class="cart-layout"><div>${cart.map(i=>`<div class="cart-row"><img src="${i.image}" alt="${i.name}"/><div><h3>${i.name}</h3><p>${i.desc}</p><span class="price">${priceOf(i)}</span></div><div class="qty"><button data-cart-qty="${i.id}" data-delta="-1">−</button><input value="${i.qty}" readonly aria-label="ຈຳນວນ"/><button data-cart-qty="${i.id}" data-delta="1">＋</button></div><b class="line-price">${priceOf(i,i.qty*i.price)}</b><button class="remove-btn" data-remove="${i.id}" aria-label="ເອົາອອກ">×</button></div>`).join('')}</div><aside class="summary"><h3>ສະຫຼຸບຄຳສັ່ງຊື້</h3><div class="summary-line"><span>ລາຄາສິນຄ້າ</span><span>${formatCurrencyTotals(totals)}</span></div><div class="summary-line"><span>ຄ່າຈັດສົ່ງ</span><span>${shipping.label}</span></div><div class="summary-line total"><span>ລວມທັງໝົດ</span><span>${formatCurrencyTotals(grand)}</span></div><a class="button" href="#checkout">ດຳເນີນການສັ່ງຊື້　→</a><small>ກວດສອບຄ່າຈັດສົ່ງກ່ອນຢືນຢັນ</small></aside></div></div>`}
function checkout(){if(!cart.length)return cartPage();let totals=currencyTotals(),shipping=cartShipping(totals),grand={...totals};if(shipping.value)grand.THB=(grand.THB||0)+shipping.value;return `<div class="page-wrap"><div class="breadcrumbs"><a href="#home">ໜ້າຫຼັກ</a>　/　<a href="#cart">ກະຕ່າສິນຄ້າ</a>　/　ຊຳລະເງິນ</div><span class="eyebrow">Almost yours</span><h1 class="page-title">ສັ່ງຊື້ສິນຄ້າ</h1><p class="page-subtitle">ປ້ອນຂໍ້ມູນຈັດສົ່ງສິນຄ້າ</p><div class="checkout-layout"><form class="checkout-form" id="checkoutForm"><h2>ຂໍ້ມູນຈັດສົ່ງ</h2><div class="form-grid"><div class="field"><label>ຊື່</label><input name="firstName" required autocomplete="given-name"/></div><div class="field"><label>ນາມສະກຸນ</label><input name="lastName" required autocomplete="family-name"/></div><div class="field"><label>ອີເມວ</label><input type="email" name="email" autocomplete="email"/></div><div class="field"><label>ເບີໂທລະສັບ</label><input type="tel" name="phone" required autocomplete="tel"/></div><div class="field full"><label>ທີ່ຢູ່</label><textarea name="address" rows="3" required autocomplete="street-address"></textarea></div><div class="field"><label>ແຂວງ</label><input name="province" required/></div><div class="field"><label>ລະຫັດໄປສະນີ</label><input name="postcode" inputmode="numeric" required/></div></div><h2 style="margin-top:24px">ວິທີຊຳລະເງິນ</h2><label class="payment-choice"><input type="radio" name="payment" value="cod" checked/> ຊຳລະເງິນປາຍທາງ</label><label class="payment-choice"><input type="radio" name="payment" value="transfer"/> ໂອນເງິນຜ່ານທະນາຄານ / ສະແກນ QR</label><div class="transfer-qr" id="transferQr" hidden><p>ສະແກນ QR ນີ້ເພື່ອຊຳລະເງິນ</p><img src="data:image/jpeg;base64," alt="QR ຮັບຊຳລະເງິນ OnePay LAPNet"/><p>ຫຼັງກົດປຸ່ມສົ່ງອໍເດີ ກະລຸນາແນບສະລິບໃນແຊັດ WhatsApp ນີ້</p></div><button class="button" type="submit" style="margin-top:18px">ສົ່ງຄຳສັ່ງຊື້ໃນ WhatsApp　·　${formatCurrencyTotals(grand)}</button></form><aside class="summary checkout-summary"><h3>ລາຍການຂອງທ່ານ</h3>${cart.map(i=>`<div class="summary-line"><span>${i.name} × ${i.qty}</span><span>${priceOf(i,i.price*i.qty)}</span></div>`).join('')}<div class="summary-line"><span>ຄ່າຈັດສົ່ງ</span><span>${shipping.label}</span></div><div class="summary-line total"><span>ລວມທັງໝົດ</span><span>${formatCurrencyTotals(grand)}</span></div></aside></div></div>`}
function render(){let hash=location.hash.slice(1)||'home';let [route,param]=hash.split('/');if(route==='shop')app.innerHTML=shop();else if(route==='product')app.innerHTML=detail(param);else if(route==='cart')app.innerHTML=cartPage();else if(route==='checkout')app.innerHTML=checkout();else if(route==='success')app.innerHTML=`<div class="page-wrap"><div class="success-state"><div class="checkmark">✓</div><h1>ขอบคุณที่เลือก Ruby Room</h1><p>เราได้รับคำสั่งซื้อของคุณแล้ว<br/>หมายเลขคำสั่งซื้อ <b>${sessionStorage.getItem('ruby-order')||'RRB-2026-001'}</b><br/>ทีมงานจะติดต่อกลับเพื่อยืนยันการจัดส่งค่ะ</p><a href="#shop" class="button">เลือกชมสินค้าต่อ</a></div></div>`;else app.innerHTML=home();app.innerHTML=toLao(app.innerHTML);save();window.scrollTo(0,0)}
function add(id,qty=1){let p=products.find(x=>x.id===id);if(!p)return;let existing=cart.find(x=>x.id===id),nextQty=Math.min(p.stock||999,(existing?existing.qty:0)+qty);existing?existing.qty=nextQty:cart.push({...p,qty:nextQty});save();toast(`ເພີ່ມ ${p.name} ໃສ່ກະຕ່າແລ້ວ`)}
document.addEventListener('click',e=>{let detailQty=e.target.closest('[data-qty]');if(detailQty){e.stopImmediatePropagation();let input=document.querySelector('#detailQty'),product=products.find(p=>p.id===document.querySelector('[data-add]')?.dataset.add);input.value=Math.min(product?.stock||99,Math.max(1,Number(input.value)+(detailQty.dataset.qty==='+'?1:-1)));return}let cartQty=e.target.closest('[data-cart-qty]');if(cartQty){e.stopImmediatePropagation();let item=cart.find(p=>p.id===cartQty.dataset.cartQty);item.qty=Math.min(item.stock||999,Math.max(1,item.qty+Number(cartQty.dataset.delta)));save();render()}},true);
document.addEventListener('click',e=>{let addBtn=e.target.closest('[data-add]');if(addBtn){e.preventDefault();let q=Number(document.querySelector('#detailQty')?.value||1);add(addBtn.dataset.add,Math.max(1,q));return}let card=e.target.closest('[data-detail]');if(card&&!e.target.closest('button')){location.hash=`product/${card.dataset.detail}`;return}let qBtn=e.target.closest('[data-qty]');if(qBtn){let input=document.querySelector('#detailQty');input.value=Math.max(1,Number(input.value)+(qBtn.dataset.qty==='+'?1:-1));return}let cartBtn=e.target.closest('[data-cart-qty]');if(cartBtn){let i=cart.find(x=>x.id===cartBtn.dataset.cartQty);i.qty=Math.max(1,i.qty+Number(cartBtn.dataset.delta));save();render();return}let rem=e.target.closest('[data-remove]');if(rem){cart=cart.filter(x=>x.id!==rem.dataset.remove);save();render();return}let cat=e.target.closest('input[name="category"]');if(cat){filter=cat.value;render();return}let mobile=e.target.closest('#menuBtn');if(mobile){document.querySelector('#mainNav').classList.toggle('open');return}let thumb=e.target.closest('.detail-thumbs button');if(thumb){document.querySelectorAll('.detail-thumbs button').forEach(x=>x.classList.remove('selected'));thumb.classList.add('selected');return}let swatch=e.target.closest('.swatches button');if(swatch){document.querySelectorAll('.swatches button').forEach(x=>x.classList.remove('selected'));swatch.classList.add('selected')}});
document.addEventListener('change',e=>{if(e.target.id==='sortProducts'){let sorted=[...products].filter(p=>(filter==='ทั้งหมด'||p.category===filter)&&(!searchTerm||p.name.toLowerCase().includes(searchTerm.toLowerCase())));if(e.target.value==='low')sorted.sort((a,b)=>a.price-b.price);if(e.target.value==='high')sorted.sort((a,b)=>b.price-a.price);document.querySelector('#shopProducts').innerHTML=sorted.map(productCard).join('')}});
document.querySelector('#searchBtn').addEventListener('click',()=>{let value=prompt('ຄົ້ນຫາສິນຄ້າໃນ Ruby Room');if(value!==null){searchTerm=value;filter='ทั้งหมด';location.hash='shop';setTimeout(()=>{let sel=document.querySelector('#sortProducts');if(sel)document.querySelector('#shopProducts').innerHTML=products.filter(p=>p.name.toLowerCase().includes(value.toLowerCase())||toLao(p.desc).toLowerCase().includes(value.toLowerCase())).map(productCard).join('')||'<p>ບໍ່ພົບສິນຄ້າທີ່ຄົ້ນຫາ</p>'},0)}});
document.addEventListener('change',e=>{if(e.target.name==='category'){filter=({'ເຄື່ອງສຳອາງ':'เมคอัพ','ບຳລຸງຜິວ':'สกินแคร์','ນ້ຳຫອມ':'น้ำหอม','ຂົນຕາປອມ':'ขนตาปลอม','ສະເປຣຍລັອກເມກອັບ':'สเปรย์ล็อกเมกอัพ'}[e.target.value]||'ทั้งหมด');render()}});
document.addEventListener('change',e=>{if(e.target.name==='payment'){let qr=document.querySelector('#transferQr');if(qr)qr.hidden=e.target.value!=='transfer'}});
window.addEventListener('hashchange',render);
document.addEventListener('submit',e=>{if(e.target.id==='checkoutForm'){e.preventDefault();const data=new FormData(e.target),totals=currencyTotals(),shipping=cartShipping(totals),grand={...totals};if(shipping.value)grand.THB=(grand.THB||0)+shipping.value;const message=['ສະບາຍດີ Ruby Room Beauty, ຂ້ອຍຂໍສັ່ງສິນຄ້າ:','',...cart.map(item=>'• '+item.name+' × '+item.qty+' — '+priceOf(item,item.qty*item.price)),'','ຄ່າສິນຄ້າ: '+formatCurrencyTotals(totals),'ຄ່າຈັດສົ່ງ: '+shipping.label,'ລວມທັງໝົດ: '+formatCurrencyTotals(grand),'ວິທີຊຳລະ: '+(data.get('payment')==='transfer'?'ໂອນເງິນ / QR':'ຊຳລະເງິນປາຍທາງ'),'','ຊື່: '+data.get('firstName')+' '+data.get('lastName'),'ເບີໂທ: '+data.get('phone'),'ອີເມວ: '+(data.get('email')||'—'),'ທີ່ຢູ່: '+data.get('address'),'ແຂວງ: '+data.get('province'),'ລະຫັດໄປສະນີ: '+data.get('postcode'),'','ຖ້າຈ່າຍຜ່ານ QR ແລ້ວ ຂ້ອຍຈະແນບສະລິບໃນແຊັດນີ້.'];const url='https://wa.me/8562092298999?text='+encodeURIComponent(message.join('\n'));const chat=window.open(url,'_blank','noopener');if(!chat)location.href=url;}if(e.target.id==='newsletterForm'){e.preventDefault();e.target.reset();toast('ຂອບໃຈທີ່ສະໝັກຮັບຂ່າວສານຈາກ Ruby Room')}});
render();
